// jasmine tests and custom assertions
(function(outputs, steps, params, stepResult, assertEqual) {
    var ohsmUtils = new x_hccc_hoc_ohs.HoCOHSMUtils();
	var INPUT_TEXT = {
		SINGLE_LINE: {
			WIDTH50_NO_SPACE: 'WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW',
			WIDTH100_NO_SPACE: 'WWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWWW',
			WIDTH50: 'WWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWW',
			WIDTH100: 'WWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWWWWWWW WWWWWWW WWWWWWWWWW WWWWWWW WWW WWWWWWWW WWWW',
			WIDTH445: 'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.'
		},
		MULTI_LINES: {
			HEIGHT4_WIDTH125_RETURNS_RN:'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. \r\nUt enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. \r\nDuis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. \r\nExcepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.',
			HEIGHT4_WIDTH125_RETURNS_N:'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. \nUt enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. \nDuis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. \nExcepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.',
			HEIGHT4_WIDTH125_RETURNS_R:'Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. \rUt enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. \rDuis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. \rExcepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.',
			HEIGHT8_WIDTH102_RETURNS_N: 'Lorem ipsum dolor sit amet, \nconsectetur adipiscing elit, \nsed do eiusmod tempor incididunt ut labore et dolore magna aliqua. \nUt enim ad minim veniam, \nquis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. \nDuis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. \nExcepteur sint occaecat cupidatat non proident, \nsunt in culpa qui officia deserunt mollit anim id est laborum.',
			HEIGHT5_WIDTH25_RETURNS_N_NO_SPACE: 'WWWWWWWWWWWWWWWWWWWWWWWWW\nWWWWWWWWWWWWWWWWWWWWWWWWW\nWWWWWWWWWWWWWWWWWWWWWWWWW\nWWWWWWWWWWWWWWWWWWWWWWWWW\nWWWWWWWWWWWWWWWWWWWWWWWWW',
			HEIGHT13_WIDTH50_RETURNS_N: 'Lorem ipsum dolor sit amet, \nconsectetur adipiscing elit, \nsed do eiusmod tempor \nincididunt ut labore et dolore magna aliqua. \nUt enim ad minim veniam, \nquis nostrud exercitation ullamco laboris nisi \nut aliquip ex ea commodo consequat. \nDuis aute irure dolor in reprehenderit in \nvoluptate velit esse cillum dolore eu fugiat \nnulla pariatur. \nExcepteur sint occaecat cupidatat non proident, \nsunt in culpa qui officia deserunt mollit anim \nid est laborum.'		}
	};

	describe('Passing a single line', function(){
		describe('that is smaller or equal as the field width', function(){
			describe('and is smaller or equal as the field height', function(){
				it('should return the string as is when smaller', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50, 100, 1);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
				it('should return the string as is when equal', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50, 50, 1);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
			});
		});
		describe('that is wider than the field width', function(){
			describe('and is smaller or equal as the field height', function(){
				it('should return the string as is', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50, 49, 2);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
				it('should return the string as is when there are NO spaces', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50_NO_SPACE, 25, 2);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
				it('should return the string as is when there are NO spaces even when multiple line wrap', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH100_NO_SPACE, 25, 4);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
			});
			describe('and is bigger than the field height', function(){
				it('should trucate the string', function(){
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50, 49, 1);
					expect(res.inputFits).toBe(false);
					expect(res.input).toEqual(INPUT_TEXT.SINGLE_LINE.WIDTH50);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});
				it('should trucate the string even if it almost fits', function(){
					var maxWidth = 25;
					var maxHeight = 2;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH50_NO_SPACE+"W", maxWidth, maxHeight); //1 char too many
					expect(res.inputFits).toBe(false);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});
				it('should trucate the string even if it almost fits and takes more than 2 lines', function(){
					var maxWidth = 25;
					var maxHeight = 4;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH100_NO_SPACE+"W", maxWidth, maxHeight); //1 char too many
					expect(res.inputFits).toBe(false);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});

				describe('and an annex is provided', function(){
					it('should truncate when annex is empty', function(){
						var maxWidth = 100;
						var maxHeight = 2;
						var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH445, maxWidth, maxHeight, "");
						expect(res.inputFits).toBe(false);
						expect(res.input).not.toEqual(res.formattedString);
						expect(res.formattedString.length).toBeLessThanOrEqual(maxHeight*maxWidth);
						expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
					});
					it('should truncate and add annex', function(){
						var maxWidth = 100;
						var maxHeight = 2;
						var annexString = "abc";
						var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH445, maxWidth, 2, annexString);
						expect(res.inputFits).toBe(false);
						expect(res.input).not.toEqual(res.formattedString);
						expect(res.formattedString.lastIndexOf(annexString)).toBeLessThanOrEqual(maxHeight*maxWidth-annexString.length);
						expect(res.formattedString.length).toBeLessThanOrEqual(maxHeight*maxWidth);
					});
					it('should throw and error when annex is longuer than maxWidth*maxHeight', function(){
						var maxWidth = 50;
						var maxHeight = 2;
						var annexString = "AnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnexAnnex1"; //101 chars
						expect(function(){
							var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.SINGLE_LINE.WIDTH445, maxWidth, 2, annexString);
						}).toThrow();
					});
				});
			});
		});
	});

	describe('Passing multiple lines ', function(){
		describe('that are smaller or equal as the field width', function(){
			describe('and have equal or fewer lines as the field height', function(){
				it('should return the string as is when smaller', function(){
					var maxWidth = 100;
					var maxHeight = 25;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT13_WIDTH50_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
				it('should return the string as is when equal', function(){
					var maxWidth = 50;
					var maxHeight = 13;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT13_WIDTH50_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
			});
			describe('and have more lines as the field height', function(){
				it('should truncate the string', function(){
					var maxWidth = 50;
					var maxHeight = 12;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT13_WIDTH50_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(false);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});
			});
		});
		describe('that are wider than the field width', function(){
			describe('and have an equal amount of lines as the field height', function(){
				it('should truncate the string', function(){ //because of word wrapping
					var maxWidth = 100;
					var maxHeight = 8;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT8_WIDTH102_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(false);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});
			});
			describe('and have an smaller amount of lines than the field height', function(){
				it('should truncate the string', function(){ //because of word wrapping
					var maxWidth = 100;
					var maxHeight = 15;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT8_WIDTH102_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(true);
					expect(res.input).toEqual(res.formattedString);
				});
			});
			describe('and have an larger amount of lines than the field height', function(){
				it('should truncate the string', function(){ //because of word wrapping
					var maxWidth = 100;
					var maxHeight = 5;
					var res = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT8_WIDTH102_RETURNS_N, maxWidth, maxHeight);
					expect(res.inputFits).toBe(false);
					expect(res.input).not.toEqual(res.formattedString);
					expect(res.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
					expect(res.input.substring(0, res.formattedString.length)).toEqual(res.formattedString);
				});
			});
		});
		describe('using different return types', function(){
			it('Should return the input when it fits', function(){
				var maxWidth = 150;
				var maxHeight = 10;
				var resrn = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_RN, maxWidth, maxHeight);
				var resn = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_N, maxWidth, maxHeight);
				var resr = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_R, maxWidth, maxHeight);
				expect(resrn.inputFits).toBe(true);
				expect(resn.inputFits).toBe(true);
				expect(resr.inputFits).toBe(true);
				expect(resrn.input).toEqual(resrn.formattedString);
				expect(resn.input).toEqual(resn.formattedString);
				expect(resr.input).toEqual(resr.formattedString);
				expect(resrn.formattedString).toContain("\r\n");
				expect(resn.formattedString).not.toContain("\r\n");
				expect(resn.formattedString).toContain("\n");
				expect(resr.formattedString).not.toContain("\r\n");
				expect(resr.formattedString).toContain("\r");
			});
			it('Should return the same output when it doesn\'t fit', function(){
				var maxWidth = 75;
				var maxHeight = 3;
				var resrn = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_RN, maxWidth, maxHeight);
				var resn = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_N, maxWidth, maxHeight);
				var resr = ohsmUtils.getFieldFormattedString(INPUT_TEXT.MULTI_LINES.HEIGHT4_WIDTH125_RETURNS_R, maxWidth, maxHeight);
				expect(resrn.inputFits).toBe(false);
				expect(resn.inputFits).toBe(false);
				expect(resr.inputFits).toBe(false);
				expect(resrn.formattedString).toEqual(resn.formattedString);
				expect(resrn.formattedString).toEqual(resr.formattedString);
				expect(resn.formattedString.length).toBeLessThanOrEqual(maxWidth*maxHeight);
				expect(resn.input.substring(0, resn.formattedString.length)).toEqual(resn.formattedString);
				expect(resrn.formattedString).not.toContain("\r\n");
				expect(resrn.formattedString).toContain("\n");
				expect(resr.formattedString).not.toContain("\r");
				expect(resr.formattedString).toContain("\n");
			});
		});
	});
})(outputs, steps, params, stepResult, assertEqual);
jasmine.getEnv().execute();
